INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64792852', 64792852, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Hilirisasi Sektor Perkebunan Tahun 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 42978852, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4', 'Posisi Konsultan Kajian Pengembangan Kebijakan Hilirisasi Sektor Perkebunan Tahun 2026 memiliki Ruang Lingkup sebagai berikut:: a) Gambaran struktur rantai nilai sektor perkebunan b) Identifikasi potensi peningkatan nilai tambah dan hilirisasi komoditas terpilih berdasarkan analisis keterkaitan dan nilai tambah. c) Analisis peluang pengembangan pasar domestik produk hilirisasi sektor perkebunan. d) Analisis peluang ekspor produk hilirisasi dan dinamika permintaan global dengan mempertimbangkan daya saing, keterkaitan perdagangan internasional, dan dinamika permintaan global. e) Identifikasi faktor pendukung dan penghambat hilirisasi mencakup aspek kelembagaan, teknologi, kemitraan, dan keberlanjutan. f) Perumusan alternatif strategi hilirisasi berbasis keterkaitan ekonomi dan peluang diversifikasi produk. g) Penyusunan kerangka konseptual dan indikatif key indicator pengembangan hilirisasi sektor pertanian, perkebunan, dan kehutanan.', '1. Memiliki latar belakang pendidikan minimal S1 di bidang Ekonomi atau Ekonomi Pembangunan 2. Memiliki Nomor Pokok Wajib Pajak (NPWP) 3. Memiliki pengalaman dalam studi terkait perencanaan pembangunan minimal dalam 2 (dua) tahun terakhir; 4. Memiliki pemahaman dan pengalaman data analisis, termasuk analisis nilai tambah (value added) serta keterkaitan antarwilayah dan antarsektor dalam konteks ekonomi global. 5. Memiliki kompetensi dalam analisis ekonomi sebagai dasar perumusan kebijakan pengembangan industri, diversifikasi ekspor, dan peningkatan daya saing wilayah; 6. Memiliki pengalaman dalam pekerjaan di bidang ekonomi dengan lingkup permasalahan skala nasional dalam kurun waktu minimal 2 (dua) tahun terakhir.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1740170);
