INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64792769', 64792769, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN KAJIAN MAKRO SEKTORAL', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 57063270, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6', 'Menghimpun data indikator makro sektoral dari sumber resmi (BPS, K/L sektoral, dan sumber relevan). Melakukan pengolahan awal data sektoral (tabulasi, grafik sederhana, tren dasar). Menyiapkan bahan pendukung analisis makro sektoral sesuai arahan Tenaga Ahli. Membantu penyusunan catatan perkembangan kinerja sektor secara berkala. Mendukung penyusunan ringkasan analitis sederhana per sektor. Menyiapkan bahan presentasi sederhana sektoral (tabel dan grafik). Menghimpun dan mengelola referensi data dan dokumen sektoral. Membantu pemantauan indikator kinerja sektor dalam konteks pembangunan nasional. Melakukan koordinasi teknis internal terkait kebutuhan data dan bahan sektoral. Melaksanakan tugas pendukung lain yang relevan dengan analisis makro sektoral sesuai arahan Tenaga Ahli.', 'Memiliki latar belakang pendidikan minimal Sarjana (S1) di bidang ekonomi, ekonomi pembangunan, statistik, perencanaan pembangunan, kebijakan publik, atau bidang lain yang relevan dengan analisis ekonomi makro. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. Memiliki pengalaman kerja di bidang pengolahan data, analisis ekonomi, perencanaan pembangunan, atau kegiatan analitis sejenis menjadi nilai tambah. Mampu menghimpun, mengolah, dan menyajikan data statistik makro dalam bentuk tabulasi, grafik sederhana, dan ringkasan angka. Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan Tenaga Ahli dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahun Mampu menghimpun, mengolah, dan menyajikan data statistik makro dalam bentuk tabulasi, grafik sederhana, dan ringkasan angka. Mampu menyiapkan bahan pendukung analisis makro berdasarkan arahan Tenaga Ahli Analis. Memiliki kemampuan dasar dalam penggunaan perangkat lunak pengolahan data dan presentasi untuk mendukung kegiatan analisis. Memiliki kemampuan komunikasi yang baik serta mampu bekerja secara cermat, sistematis, dan sesuai arahan. Mampu bekerja secara mandiri maupun dalam tim serta mendukung koordinasi teknis internal. Memiliki integritas, etika kerja, dan tanggung jawab yang tinggi dalam pelaksanaan tugas. Mampu menjaga kerahasiaan data, informasi, dan dokumen yang diperoleh selama pelaksanaan kegiatan. Tidak sedang menjalani sanksi administratif atau proses hukum serta tidak memiliki konflik kepentingan yang dapat mempengaruhi pelaksanaan tugas.an terakhir; Tidak sedang menjalani sanksi administratif atau proses hukum serta tidak memiliki konflik kepentingan yang dapat memengaruhi pelaksanaan tugas. Bekerja berdasarkan pendekatan berbasis keluaran (output based) serta memiliki komitmen untuk hadir secara fisik dan melakukan perjalanan dinas apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1741362);
