INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64793383', 64793383, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENDAMPINGAN KEGIATAN TRANSFORMASI INDONESIA', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 57249816, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6', 'Posisi Jasa Konsultan Asisten Direktur Eksekutif Sekretariat Transformasi Indonesia memiliki Ruang Lingkup sebagai berikut: Membantu Direktur Eksekutif dalam mengawal 45 Indikator Utama Pembangunan (IUP) RPJPN 2025-2045: Membantu melakukan pemantauan secara berkala atas perkembangan capaian 45 IUP; Membantu mengidentifikasi dan memastikan setiap IUP telah dijabarkan hingga level kebijakan dan intervensi yang relevan; Membantu mengidentifikasi isu dan hambatan implementasi yang memengaruhi pencapaian indikator; Membantu menyusun hasil pemantauan secara berkala dalam format dashboard atau laporan singkat. Membantu Direktur Eksekutif dalam mengawal pertumbuhan ekonomi 8%. Membantu Direktur Eksekutif dalam penyusunan Peraturan Pemerintah (PP) Turunan RPJPN 2025-2045. Membantu Direktur Eksekutif dalam melakukan pendampingan Sekretariat Transformasi di Daerah terpilih, dengan fokus pengendalian perencanaan. Membantu Direktur Eksekutif dalam pendampingan penyusunan RKP Tahun 2027. Membantu Direktur Eksekutif tugas-tugas lainnya dalam rangka pencapaian tujuan Sekretariat Transformasi Indonesia.', 'Pendidikan Jasa Konsultan minimal S1 bidang Ilmu Ekonomi/Ekonomi Pembangunan dan dapat dibuktikan dengan Ijazah atau dokumen resmi kelulusan atau sertifikat kelulusan; Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak; Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan Warga Negara Indonesia (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; Bekerja berdasarkan output keluaran (Output Based), dan memiliki komitmen untuk hadir secara fisik apabila dibutuhkan dan melakukan perjalanan apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1742174);
