INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64794104', 64794104, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN KOORDINASI TEKNIS PENGAWALAN PILOT PROJECT SEKRETARIAT TRANSFORMASI INDONESIA', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 55636362, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6', 'Posisi Jasa Konsultan Koordinasi Teknis Pengawalan Sekretariat Transformasi Indonesia memiliki Ruang Lingkup sebagai berikut: Melakukan pengawalan Sekretariat Transformasi Daerah, dalam melakukan fungsi pengendalian pelaksanaan: Melakukan koordinasi dengan sektor terkait di Kementerian PPN/Bappenas dalam rangka menyelesaikan permasalahan dan hambatan (debottlenecking) pelaksanaan Sekretariat Transformasi pada provinsi terpilih; Melakukan koordinasi dengan Sekretariat Transformasi provinsi terpilih dalam rangka memberikan solusi alternatif atas hambatan proyek; Melakukan tindak lanjut hasil diskusi dan laporan yang dilakukan rapat rutin tim sekretariat Melakukan Pendampingan Monitoring dan Evaluasi Membantu Direktur Eksekutif dalam melakukan pendampingan terhadap penyusunan PP sebagai penjabaran misi dari UU 59/2024: Membantu analisis substansi dan penyusunan bahan teknis PP, termasuk penelaahan regulasi, identifikasi isu strategis, serta perumusan kebutuhan regulasi yang menjadi dasar penyusunan PP; Melakukan koordinasi dengan sektor dan pemangku kepentingan ekonomi (investor, asosiasi, UMKM) dalam rangka menghimpun masukan, mengidentifikasi bottleneck, serta memastikan sinkronisasi kebijakan lintas sektor; membantu penyelarasan arah kebijakan dan menyusun laporan hasil konsultasi dan tindak lanjut rapat koordinasi yang mendukung proses finalisasi substansi PP. Membantu mengintegrasikan hasil analisis dan masukan sektoral ke dalam rumusan kebijakan agar substansi PP lebih konsisten, implementatif, dan selaras dengan tujuan UU 59/2024. Membantu Direktur Eksekutif dalam mengawal pertumbuhan ekonomi 8%. Membantu Direktur Eksekutif dalam pendampingan penyusunan RKP Tahun 2027. Membantu Direktur Eksekutif dalam mempersiapkan agenda-agenda (seperti rapat bulanan/focus group discussion (FGD)/ kunjungan lapangan) dalam rangka mendukung pencapaian tujuan Sekretariat Transformasi Indonesia. Membantu Direktur Eksekutif tugas-tugas lainnya dalam rangka pencapaian tujuan Sekretariat Transformasi Indonesia.', 'Pendidikan Jasa Konsultan minimal S1 bidang Ekonomi dan dapat dibuktikan dengan Ijazah atau dokumen resmi kelulusan atau sertifikat kelulusan; Memiliki pengalaman baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dan dapat dibuktikan dengan surat kontrak dan atau surat pengalaman; Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan Warga Negara Indonesia (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; Bekerja berdasarkan output keluaran (Output Based), dan memiliki komitmen untuk hadir secara fisik apabila dibutuhkan dan melakukan perjalanan apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1743419);
