INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64756417', 64756417, 'analyze_legacy', 'Kab. Banjarnegara', 'kabkota', 'Dinas Kesehatan', 'Pengadaan Belanja Modal Alat Kedokteran Gigi Puskesmas Rakit 1', 'Barang', 'E-Purchasing', 'Jawa Tengah, Banjarnegara (Kab.)', 25000000, 'January 2026', 'BLUD', 1, 1, '1 tahun', 'Pengadaan Belanja Modal Alat Kedokteran Gigi Puskesmas Rakit 1 berupa alat scaller dan Dental Airosol', 'SPESIFIKASI TEKNIS ALAT SCALER (ULTRASONIC DENTAL SCALER) 1️⃣ Jenis Ultrasonic Scaler Digunakan untuk pembersihan karang gigi (scaling supragingival & ringan subgingival) 2️⃣ Spesifikasi Teknis Utama Parameter Spesifikasi Minimal Sistem kerja Ultrasonic (Piezo / Magnetostrictive) Frekuensi getaran 25.000 – 30.000 Hz Daya listrik ≤ 150 Watt Tegangan 220 V / 50–60 Hz Kontrol daya Putar / Digital adjustable Sistem pendingin Water spray terintegrasi Aliran air Adjustable Handpiece Autoclavable (≥ 135°C) Kabel handpiece Fleksibel, tahan panas Ujung scaler (tips) Minimal 3–5 pcs (G1/G2/P1) Material tips Stainless steel medis Noise level Rendah / tidak mengganggu pasien Sistem proteksi Overheat protection Foot switch Ada (opsional tapi direkomendasikan) 3️⃣ Fitur Wajib untuk Puskesmas ✅ Mudah dioperasikan ✅ Cocok untuk tindakan rutin BPJS ✅ Perawatan & spare part mudah ✅ Bisa digunakan lama (heavy use) ✅ Aman untuk pasien umum 4️⃣ Standar & Keamanan CE / ISO / FDA (salah satu) Material medical grade Aman untuk penggunaan klinik pemerintah 5️⃣ Aksesori Minimal Unit scaler Handpiece Ujung scaler (≥ 3 pcs) Selang air Kunci tips Buku manual Garansi resmi min. 1 tahun 🔹 SPESIFIKASI TEKNIS DENTAL AEROSOL (PENGENDALI AEROSOL) Digunakan untuk mengurangi penyebaran aerosol & droplet saat scaling dan tindakan gigi. 🔸 OPSI 1: DENTAL AEROSOL SUCTION / EXTRA ORAL SUCTION (REKOMENDASI) Spesifikasi Teknis Parameter Spesifikasi Minimal Jenis Extra Oral Suction Dental Fungsi Menyedot aerosol & droplet Daya hisap ≥ 15–20 kPa Airflow ≥ 250–300 m³/jam Filter HEPA H13 / H14 Filter tambahan Carbon filter (bau & partikel) Noise level ≤ 65 dB Daya listrik ≤ 1.000 Watt Tegangan 220 V Lengan suction Fleksibel, adjustable Mobilitas Roda (portable) Operasional Continuous use Fitur Wajib ✅ Menangkap aerosol saat scaling ✅ Mengurangi risiko infeksi silang ✅ Mudah dipindah antar ruangan ✅ Filter mudah diganti 🔸 OPSI 2: DENTAL AEROSOL SHIELD (Alternatif Hemat) Jika belum tersedia suction aerosol, bisa digunakan: Dental Aerosol Shield / Box transparan Material akrilik / polycarbonate Mudah dibersihkan & disterilkan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1748665);
